import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"怨上","description":"","frontmatter":{"title":"怨上","date":"2026-11-24T00:00:00.000Z","seq":58,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"王逸","source_book":"楚辞","prev":{"text":"逢尤","link":"/blogs/楚辞/逢尤.html"},"next":{"text":"疾世","link":"/blogs/楚辞/疾世.html"}},"headers":[],"relativePath":"blogs/楚辞/怨上.md","filePath":"blogs/楚辞/怨上.md"}'),o={name:"blogs/楚辞/怨上.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="怨上" tabindex="-1">怨上 <a class="header-anchor" href="#怨上" aria-label="Permalink to &quot;怨上&quot;">​</a></h1><p class="poem-meta">先秦 · 王逸　·　九思</p><div class="poem"><p class="poem-stanza">令尹兮謷謷，群司兮譨譨。</p><p class="poem-stanza">哀哉兮淈淈，上下兮同流。</p><p class="poem-stanza">菽藟兮蔓衍，芳虈兮挫枯。</p><p class="poem-stanza">硃紫兮杂乱，曾莫兮别诸。</p><p class="poem-stanza">倚此兮岩穴，永思兮窈悠。</p><p class="poem-stanza">嗟怀兮眩惑，用志兮不昭。</p><p class="poem-stanza">将丧兮玉斗，遗失兮钮枢。</p><p class="poem-stanza">我心兮煎熬，惟是兮用忧。</p><p class="poem-stanza">进恶兮九旬，复顾兮彭务。</p><p class="poem-stanza">拟斯兮二踪，未知兮所投。</p><p class="poem-stanza">谣吟兮中野，上察兮璇玑。</p><p class="poem-stanza">大火兮西睨，摄提兮运低。</p><p class="poem-stanza">雷霆兮硠磕，雹霰兮霏霏。</p><p class="poem-stanza">奔电兮光晃，凉风兮怆悽。</p><p class="poem-stanza">鸟兽兮惊骇，相从兮宿栖。</p><p class="poem-stanza">鸳鸯兮噰噰，狐狸兮徾徾。</p><p class="poem-stanza">哀吾兮介特，独处兮罔依。</p><p class="poem-stanza">蝼蛄兮鸣东，蟊蠽兮号西。</p><p class="poem-stanza">蛓缘兮我裳，蠋入兮我怀。</p><p class="poem-stanza">虫豸兮夹余，惆怅兮自悲。</p><p class="poem-stanza">伫立兮忉怛，心结縎兮折摧。</p></div>',3)])])}const d=s(o,[["render",l]]);export{z as __pageData,d as default};
